{
     "title": "CSCI-636: Information Retrieval Foundations",
     "learningObjectives": [
       "Define and explain the core components of traditional retrieval models, including TF-IDF and BM25, and describe how they rank documents based on term-",
       "Explain the role of neural reranking and retrieval techniques in modern search systems, and describe how they improve relevance by leveraging deep",
       "Evaluate search engine performance using standard metrics and describe how to design a controlled experiment to test retrieval components."
     ],
     "beats": [
       {
         "title": "Introduction to Search Engine Architecture",
         "claim": "Search engines rely on a structured pipeline that transforms user queries into ranked document results through indexing, retrieval, and ranking stages.",
         "example": "A user types 'machine learning basics' into a search bar, and the system returns a ranked list of documents matching the query terms.",
         "visualDirection": "Display a horizontal flowchart with three labeled boxes: Query Input, Index/Retrieval, and Ranked Results, connected by arrows indicating data flow.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Query Processing and Preprocessing",
         "claim": "Raw user queries undergo tokenization, stop-word removal, and stemming or lemmatization to normalize text before matching against the document index.",
         "example": "The query 'running shoes' is tokenized into ['running', 'shoes'], with 'running' stemmed to 'run' to match variations like 'runs' or 'ran'.",
         "visualDirection": "Show a split-screen graphic: left side shows raw query text, right side shows processed tokens with arrows indicating preprocessing steps.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Traditional Retrieval: TF-IDF",
         "claim": "The Term Frequency-Inverse Document Frequency (TF-IDF) model ranks documents by calculating the product of a term's frequency within a document and its inverse frequency across the",
         "example": "A term appearing frequently in one document but rarely across the corpus receives a high TF-IDF score, boosting its ranking position.",
         "visualDirection": "Render a bar chart comparing TF-IDF scores for three terms across two documents, highlighting the inverse document frequency component.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Traditional Retrieval: BM25",
         "claim": "The BM25 algorithm refines TF-IDF by incorporating position weighting, query length normalization, and a saturation function to reduce the impact of overly frequent terms.",
         "example": "A term appearing at the beginning of a document receives a higher position weight, while the saturation function prevents rare terms from dominating the score.",
         "visualDirection": "Display a formula breakdown with labeled components: position weight, query length normalization, and saturation function, alongside a sample score calculation.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Modern Retrieval: Neural Reranking",
         "claim": "Neural reranking models use deep learning architectures to re-score initially retrieved documents by learning complex semantic relationships between queries and passages.",
         "example": "A transformer-based reranker reorders a top-100 list of documents by analyzing contextual embeddings, promoting documents with higher semantic alignment.",
         "visualDirection": "Illustrate a two-stage pipeline: first stage shows traditional retrieval output, second stage shows neural reranker adjusting document order with attention visualization.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Modern Retrieval: Dense Retrieval",
         "claim": "Dense retrieval techniques map queries and documents into a shared vector space using neural encoders, enabling similarity search through cosine distance calculations.",
         "example": "A query and a document are encoded into 768-dimensional vectors, and the system retrieves the top-k documents with the smallest cosine distance to the query vector.",
         "visualDirection": "Show a 2D projection of query and document vectors with distance metrics, emphasizing the shared embedding space and cosine similarity calculation.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Search Engine Evaluation Metrics",
         "claim": "Search performance is evaluated using metrics like precision, recall, mean average precision (MAP), and nDCG, which measure relevance and ranking quality across result sets.",
         "example": "MAP calculates the average precision at the top of the ranked list, providing a single score that reflects overall ranking effectiveness.",
         "visualDirection": "Present a table comparing precision, recall, MAP, and nDCG with brief definitions and a sample calculation for MAP.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Search Applications: Conversational IR",
         "claim": "Conversational information retrieval systems maintain dialogue state across multiple turns, using context-aware retrieval to answer follow-up questions accurately.",
         "example": "After a user asks 'What is NLP?', the system retrieves relevant documents and uses the context to answer 'How does NLP work?' in the next turn.",
         "visualDirection": "Display a dialogue flow with user queries and system responses, highlighting context tracking and retrieval steps at each turn.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Search Applications: Enterprise Search",
         "claim": "Enterprise search systems integrate with organizational data sources, enforce access controls, and support faceted navigation to help users find internal documents efficiently.",
         "example": "An employee searches for 'Q3 financial report' and filters results by department, date range, and document type to locate the correct internal document.",
         "visualDirection": "Show a dashboard with search bar, filter panel, and results list, emphasizing access controls and faceted navigation features.",
         "sourceIds": ["rit-csci-636"]
       },
       {
         "title": "Experimental Design for Retrieval Components",
         "claim": "Designing experiments for search components requires defining a baseline, selecting a test corpus, controlling variables, and evaluating performance using standardized metrics.",
         "example": "Compare a TF-IDF baseline against a BM25 model on a news corpus, measuring MAP and nDCG to determine which ranking algorithm performs better.",
         "visualDirection": "Create a comparison table with columns for Baseline, Model, Corpus, Metrics, and Results, highlighting controlled experimental variables.",
         "sourceIds": ["rit-csci-636"]
       }
     ]
   }
